// Brand fonts for the media kit PDF, embedded as base64 TTF (Latin subset).
// jsPDF can only draw its built-in fonts unless a TTF is registered, so these
// are what let the PDF use the same type as the site: Archivo Black for
// display, IBM Plex Sans for body, IBM Plex Mono for labels. Sources are the
// Google Fonts releases (SIL Open Font License). This module is only ever
// loaded through a dynamic import() when someone downloads a media kit, so it
// stays out of the main bundle.
export const ARCHIVO_BLACK =
  "";
export const PLEX_SANS_REGULAR =
  "";
export const PLEX_SANS_SEMIBOLD =
  "";
export const PLEX_MONO_MEDIUM =
  "";
export const PLEX_MONO_BOLD =
  "";
